import { Scene, Box, Sphere, Light, Color, Vec3 } from "retiam";

const scene = new Scene({ canvas });

// 1. Configure directional sunlight source
const sun = new Light({
    position: [10, 15, 12],
    color: Color.fromHex("#ffffff"),
    intensity: 1.5,
    castShadow: true
});
scene.add(sun);

// 2. Add ground receiving shadow
const ground = new Box(20, 0.2, 20, {
    position: [0, -1, 0],
    fill: Color.fromHex("#334155")
});
ground.RECEIVE_SHADOW = true;
ground.CAST_SHADOW = false;
scene.add(ground);

// 3. Add shadow-casting subject
const sphere = new Sphere(1.5, {
    position: [0, 2, 0],
    fill: Color.fromHex("#38bdf8")
});
sphere.CAST_SHADOW = true;
sphere.RECEIVE_SHADOW = true;
scene.add(sphere);
